"""Algorithm 3 — Exact lift by the fibrewise variance law.

Computes Delta R^2 = W / T for a finite design, where W is the total
within-fibre sum of squares of the target over the fibres of the base
statistic and T is the total sum of squares.  No optimiser is involved:
the "regression result" is a deterministic arithmetic ratio.
"""

from __future__ import annotations

import math
from collections import defaultdict
from typing import Callable, Dict, List, Sequence, Tuple


def factorize(n: int) -> Dict[int, int]:
    f: Dict[int, int] = {}
    m, p = n, 2
    while p * p <= m:
        while m % p == 0:
            f[p] = f.get(p, 0) + 1
            m //= p
        p += 1
    if m > 1:
        f[m] = f.get(m, 0) + 1
    return f


def radical(n: int) -> int:
    r = 1
    for p in factorize(n):
        r *= p
    return r


def prime_power_excess(n: int) -> float:
    return sum((e - 1) * math.log(p) for p, e in factorize(n).items())


def sum_of_squares(values: Sequence[float]) -> float:
    if not values:
        return 0.0
    mean = sum(values) / len(values)
    return sum((v - mean) ** 2 for v in values)


def fibrewise_lift(
    design: Sequence[int],
    base: Callable[[int], int] = radical,
    target: Callable[[int], float] = prime_power_excess,
) -> Tuple[float, float, float, Dict[int, List[int]]]:
    """Return (Delta R^2, W, T, fibres) for the given design.

    Steps:
      1. group the design into fibres of the base statistic;
      2. W  <- sum over fibres of the within-fibre sum of squares of the target;
      3. T  <- total sum of squares of the target over the whole design;
      4. Delta R^2 <- W / T   (zero by convention if T = 0).

    Complexity: O(|S|) after factorisation of each element; the factorisations
    dominate at O(|S| sqrt(max S)) with trial division, or O(|S|) with a sieve.
    """
    fibres: Dict[int, List[int]] = defaultdict(list)
    for n in design:
        fibres[base(n)].append(n)
    within = sum(sum_of_squares([target(n) for n in group])
                 for group in fibres.values())
    total = sum_of_squares([target(n) for n in design])
    lift = within / total if total > 0 else 0.0
    return lift, within, total, dict(fibres)


if __name__ == "__main__":
    log2 = math.log(2)

    lift, w, t, fibres = fibrewise_lift([2, 3, 4])
    print("design {2,3,4}:")
    print(f"  fibres          {fibres}")
    print(f"  W  = {w:.8f}   (theory {log2 ** 2 / 2:.8f})")
    print(f"  T  = {t:.8f}   (theory {2 / 3 * log2 ** 2:.8f})")
    print(f"  dR2 = {lift:.8f}  (theory 0.75)")

    print("\n2-smooth tower: single fibre, dR2 = 1")
    for m in (2, 4, 8):
        tower = [2 ** k for k in range(1, m + 1)]
        lift, _, t, _ = fibrewise_lift(tower)
        print(f"  m = {m}: T = {t:.6f} (theory "
              f"{m * (m * m - 1) / 12 * log2 ** 2:.6f}), dR2 = {lift:.6f}")

    print("\ny-smooth pools up to 20000: the lift decreases as y grows")
    for y in (5, 11, 23, 53):
        pool = [n for n in range(2, 20001) if max(factorize(n)) <= y]
        lift, _, _, fib = fibrewise_lift(pool)
        print(f"  y = {y:>3}: |pool| = {len(pool):>5}, #radicals = {len(fib):>5}, "
              f"dR2 = {lift:.4f}")

"""Algorithm 4 — Graded layer profile and its geometric decay.

The level-k layer of the prime-power excess is L_k(n) = sum_{p^k | n} log p,
and E = L_2 + L_3 + ...   Its window mass obeys the exact law

    L_k(N) := sum_{n <= N} L_k(n) = sum_{p <= N^(1/k)} log p * floor(N / p^k),

from which L_{k+1}(N) <= L_k(N) / 2 follows termwise.
"""

from __future__ import annotations

import math
from typing import Dict, List


def primes_up_to(limit: int) -> List[int]:
    if limit < 2:
        return []
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(math.isqrt(limit)) + 1):
        if sieve[i]:
            for j in range(i * i, limit + 1, i):
                sieve[j] = False
    return [i for i, ok in enumerate(sieve) if ok]


def layer_mass(k: int, n_max: int) -> float:
    """L_k(N) = sum_{p} log p * floor(N / p^k); zero as soon as N < 2^k."""
    if k < 1 or n_max < 2 ** k:
        return 0.0
    bound = int(round(n_max ** (1.0 / k))) + 2
    return sum(math.log(p) * (n_max // p ** k)
               for p in primes_up_to(bound) if p ** k <= n_max)


def layer_profile(n_max: int) -> Dict[int, float]:
    """All non-zero layer masses of the window [1, N], keyed by level.

    The profile has at most log_2 N entries and costs O(sqrt(N) log N) to build.
    """
    profile: Dict[int, float] = {}
    k = 2
    while 2 ** k <= n_max:
        mass = layer_mass(k, n_max)
        if mass == 0.0:
            break
        profile[k] = mass
        k += 1
    return profile


if __name__ == "__main__":
    for n_max in (10 ** 4, 10 ** 6):
        profile = layer_profile(n_max)
        total = sum(profile.values())
        print(f"N = {n_max}:  total prime-power mass = {total:.3f}")
        prev = None
        for k, mass in sorted(profile.items()):
            ratio = "" if prev is None else f"  ratio {mass / prev:.4f}"
            print(f"    L_{k:<2} = {mass:>12.4f}{ratio}")
            assert prev is None or mass <= prev / 2 + 1e-9
            prev = mass
        l2 = profile[2]
        print(f"    sandwich: {l2:.3f} <= {total:.3f} <= {2 * l2:.3f}\n")
